export const CAT_DIVIDIDAS = { casa: ['vivienda', 'servicios', 'hogar', 'suscripciones', 'transporte'], familia: ['compras', 'super', 'educacion', 'deporte', 'mascotas', 'hogar', 'ocio', 'salud', 'otros'], transporte: ['transporte', 'vehiculo'], salud: ['salud', 'compras', 'deporte'], compras: ['compras', 'ocio', 'viajes', 'regalos'] };
